// Generated by scripts/sync-website-demos.mjs from the website tool pages. Edit the website copy and re-run.
import { CheckIcon, Trash2Icon } from 'lucide-react'

import { Btn, DemoStage, PanelChrome, type Build } from '@/app/demos/stage'
import { cn } from '@/shared/utils/cn'

import {
  CAPTIONS,
  CLEAN,
  DIRTY_URL,
  ENCODE_SAMPLE,
  ENCODED,
  EXAMPLE,
  PARAMS,
  PARTS,
  TAB_LABELS,
} from './script'

const build: Build = ({ tl, q, qa, step, final, move, click, type, wait, cursorOut }) => {
  step(0)
  move('input', { at: 0.25, ax: 0.15 })
  click('input')
  tl.set(q('ph'), { opacity: 0 })
  type('input-text', EXAMPLE, { speed: 0.018 })

  step(1, '+=0.45')
  tl.fromTo(
    qa('part'),
    { opacity: 0, y: 6 },
    { opacity: 1, y: 0, duration: 0.25, stagger: 0.06 },
    0,
  )
  tl.fromTo(
    qa('param'),
    { opacity: 0, x: -8 },
    { opacity: 1, x: 0, duration: 0.2, stagger: 0.08 },
    0.15,
  )

  step(2, '+=0.35')
  move('tab-encode')
  click('tab-encode')
  tl.to(q('tab-parse'), { opacity: 0.55, duration: 0.2 }, '<')
  tl.to(q('tab-encode'), { opacity: 1, duration: 0.2 }, '<')
  tl.to(q('panel-parse'), { opacity: 0, y: -12, duration: 0.35 }, '<0.05')
  tl.fromTo(q('panel-encode'), { opacity: 0, y: 12 }, { opacity: 1, y: 0, duration: 0.35 }, '<0.15')
  move('encode-box', { at: '<0.2' })
  click('encode-box')
  type('encode-text', ENCODE_SAMPLE, { speed: 0.025 })
  tl.fromTo(q('encoded-out'), { opacity: 0 }, { opacity: 1, duration: 0.25 }, '<0.3')

  step(3, '+=0.4')
  move('tab-clean')
  click('tab-clean')
  tl.to([q('tab-parse'), q('tab-encode')], { opacity: 0.55, duration: 0.2 }, '<')
  tl.to(q('tab-clean'), { opacity: 1, duration: 0.2 }, '<')
  tl.to(q('panel-encode'), { opacity: 0, duration: 0.25 }, '<0.05')
  tl.fromTo(q('panel-clean'), { opacity: 0 }, { opacity: 1, duration: 0.3 }, '<0.1')
  tl.set(q('input-text'), { textContent: DIRTY_URL })
  tl.fromTo(
    q('removed'),
    { opacity: 0, height: 0 },
    { opacity: 1, height: 'auto', duration: 0.35 },
    '<0.15',
  )
  tl.fromTo(q('clean-out'), { opacity: 0 }, { opacity: 1, duration: 0.3 }, '<0.2')
  tl.to([q('tab-parse'), q('tab-encode')], { opacity: 1, duration: 0.2 }, '+=0.35')
  cursorOut('+=0.2')
  final()
  wait(1.5)
}

export default function Demo() {
  return (
    <DemoStage
      label="URL Toolkit parsing a shop link, encoding text and stripping tracking parameters"
      steps={CAPTIONS}
      build={build}
    >
      <PanelChrome>
        <div className="flex h-full flex-col gap-2">
          <div className="flex gap-1 rounded-full border border-line bg-canvas/70 p-1 text-[10px]">
            {TAB_LABELS.map((label, index) => (
              <span
                key={label}
                data-d={`tab-${['parse', 'encode', 'clean'][index]}`}
                className={cn(
                  'rounded-full px-2.5 py-1 transition-opacity',
                  index === 0 ? 'bg-ink/10 text-ink' : 'text-muted',
                )}
              >
                {label}
              </span>
            ))}
          </div>

          <div className="relative min-h-[220px] flex-1">
            <div data-d="panel-parse" className="absolute inset-0 flex flex-col gap-2">
              <div
                data-d="input"
                className="min-h-[52px] rounded-lg border border-line bg-canvas/80 p-2 font-mono text-[10px] leading-relaxed"
              >
                <span data-d="ph" className="text-muted">
                  {EXAMPLE}
                </span>
                <span data-d="input-text" className="demo-caret break-all text-ink-soft" />
              </div>
              <div className="grid grid-cols-2 gap-1.5">
                {(
                  [
                    ['protocol', PARTS.protocol],
                    ['host', PARTS.host],
                    ['port', PARTS.port],
                    ['path', PARTS.path],
                    ['fragment', PARTS.fragment],
                  ] as const
                ).map(([key, value]) => (
                  <div
                    key={key}
                    data-d="part"
                    className="rounded-md border border-line bg-surface/60 p-1.5 opacity-0"
                  >
                    <p className="text-[9px] text-muted capitalize">{key}</p>
                    <p className="truncate font-mono text-[10px] text-ink">{value}</p>
                  </div>
                ))}
              </div>
              <p className="text-[9px] font-medium text-muted">
                Query parameters ({PARAMS.length})
              </p>
              <div className="space-y-1">
                {PARAMS.map((param) => (
                  <div
                    key={param.key}
                    data-d="param"
                    className="flex items-center gap-1 rounded border border-line bg-canvas/50 px-1.5 py-1 opacity-0"
                  >
                    <code className="text-[10px] font-medium text-[var(--accent)]">
                      {param.key}
                    </code>
                    <span className="text-muted">=</span>
                    <code className="min-w-0 flex-1 truncate font-mono text-[10px] text-ink-soft">
                      {param.value}
                    </code>
                    <Trash2Icon className="size-2.5 shrink-0 text-muted" aria-hidden />
                  </div>
                ))}
              </div>
            </div>

            <div data-d="panel-encode" className="absolute inset-0 flex flex-col gap-2 opacity-0">
              <div
                data-d="encode-box"
                className="min-h-[52px] rounded-lg border border-line bg-canvas/80 p-2 text-[10px]"
              >
                <span data-d="encode-text" className="demo-caret text-ink-soft" />
              </div>
              <div
                data-d="encoded-out"
                className="rounded-lg border border-line bg-surface/60 p-2 opacity-0"
              >
                <p className="text-[9px] text-muted">Encoded</p>
                <code className="break-all font-mono text-[10px] text-ink">{ENCODED}</code>
              </div>
            </div>

            <div data-d="panel-clean" className="absolute inset-0 flex flex-col gap-2 opacity-0">
              <div className="min-h-[52px] rounded-lg border border-line bg-canvas/80 p-2 font-mono text-[10px] leading-relaxed text-ink-soft">
                {DIRTY_URL}
              </div>
              <div
                data-d="removed"
                className="overflow-hidden rounded-lg border border-amber/40 bg-amber/10 p-2 text-[10px] text-amber opacity-0"
              >
                Removed: {CLEAN.removed.join(', ')}
              </div>
              <div
                data-d="clean-out"
                className="flex items-center gap-2 rounded-lg border border-line bg-surface/60 p-2 opacity-0"
              >
                <CheckIcon className="size-3 shrink-0 text-emerald" aria-hidden />
                <code className="min-w-0 flex-1 break-all font-mono text-[10px] text-ink">
                  {CLEAN.url.toString()}
                </code>
              </div>
            </div>
          </div>

          <div className="flex gap-2">
            <Btn d="tab-parse" primary className="pointer-events-none opacity-80">
              Parse
            </Btn>
          </div>
        </div>
      </PanelChrome>
    </DemoStage>
  )
}
